function executeExpiredPendingWithdrawal(
        uint256 withdrawalId
    ) external whenNotPaused nonReentrant {
        _checkWithdrawalExists(withdrawalId, true);
        _checkWithdrawalNotExecuted(withdrawalId);
        Withdrawal storage withdrawal = withdrawals[withdrawalId];
        _refillWithdrawHotAmount(withdrawal.token);
        _checkWithdrawalPending(withdrawalId);
        if (withdrawal.paused) {
            revert WithdrawalPaused();
        }
        if (block.timestamp < withdrawal.timestamp + pendingWithdrawChallengePeriod) {
            revert ChallengePeriodNotExpired();
        }
        _executeWithdrawal(withdrawalId, true, false, false, 0);
    }

function _checkWithdrawalExists(
        uint256 id,
        bool shouldExist
    ) internal view {
        bool isExisting = withdrawals[id].timestamp > 0;
        if (isExisting != shouldExist) {
            revert WithdrawalExistenceCheckFailed();
        }
    }

function _checkWithdrawalNotExecuted(uint256 id) internal view {
        if (withdrawals[id].executed) {
            revert WithdrawalAlreadyExecuted();
        }
    }

function _refillWithdrawHotAmount(address token) internal {
        TokenInfo storage tokenInfo = supportedTokens[token];
        uint256 refillPeriod = block.timestamp - tokenInfo.lastRefillTimestamp;
        if (refillPeriod == 0) {
            return;
        }
        uint256 hardCap = getHardCap(token);
        uint256 refillAmount = (hardCap *
            tokenInfo.refillRateMps *
            refillPeriod) / 1000000;
        uint256 appliedRefillAmount = refillAmount;
        if (tokenInfo.usedWithdrawHotAmount < refillAmount) {
            appliedRefillAmount = tokenInfo.usedWithdrawHotAmount;
            tokenInfo.usedWithdrawHotAmount = 0;
        } else {
            tokenInfo.usedWithdrawHotAmount -= refillAmount;
        }
        tokenInfo.lastRefillTimestamp = block.timestamp;
        emit WithdrawHotAmountRefilled(
            tokenInfo.token,
            appliedRefillAmount,
            tokenInfo.usedWithdrawHotAmount
        );
    }

function _checkWithdrawalPending(uint256 id) internal view {
        if (!withdrawals[id].pending) {
            revert WithdrawalMustBePending();
        }
    }

function _executeWithdrawal(
        uint256 withdrawalId,
        bool isPending,
        bool isFlushed,
        bool isPaused,
        uint256 nonce
    ) internal {
        Withdrawal storage withdrawal = withdrawals[withdrawalId];
        withdrawal.executed = true;
        _transfer(
            payable(withdrawal.receiver),
            withdrawal.token,
            withdrawal.amount,
            withdrawal.fee
        );
        emit WithdrawExecuted(
            withdrawalId,
            withdrawal.receiver,
            withdrawal.token,
            withdrawal.amount,
            withdrawal.fee,
            isPending,
            isFlushed,
            isPaused,
            nonce
        );
    }

function getHardCap(address token) public view returns (uint256) {
        TokenInfo storage tokenInfo = supportedTokens[token];
        uint256 balance = token == address(0)
            ? address(this).balance
            : IERC20(token).balanceOf(address(this));
        return (balance * tokenInfo.hardCapRatioBps) / 10000;
    }

function _transfer(
        address payable to,
        address token,
        uint256 amount,
        uint256 fee
    ) private {
        if (amount == 0) {
            revert ZeroAmount();
        }
        if (fee >= amount) {
            revert InvalidParameters();
        }
        if (token == address(0)) {
            Address.sendValue(payable(to), amount - fee);
            if (fee > 0) {
                fees[token] += fee;
            }
        } else {
            SafeERC20.safeTransfer(IERC20(token), to, amount - fee);
            if (fee > 0) {
                fees[token] += fee;
            }
        }
    }

function sendValue(address payable recipient, uint256 amount) internal {
        if (address(this).balance < amount) {
            revert Errors.InsufficientBalance(address(this).balance, amount);
        }
        if (LowLevelCall.callNoReturn(recipient, amount, "")) {
            // call successful, nothing to do
            return;
        } else if (LowLevelCall.returnDataSize() > 0) {
            LowLevelCall.bubbleRevert();
        } else {
            revert Errors.FailedCall();
        }
    }

function safeTransfer(IERC20 token, address to, uint256 value) internal {
        if (!_safeTransfer(token, to, value, true)) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function callNoReturn(address target, bytes memory data) internal returns (bool success) {
        return callNoReturn(target, 0, data);
    }

function callNoReturn(address target, uint256 value, bytes memory data) internal returns (bool success) {
        assembly ("memory-safe") {
            success := call(gas(), target, value, add(data, 0x20), mload(data), 0x00, 0x00)
        }
    }

function lock(uint256 ruleId) public nonReentrant {
        require(!isPausingForOperation, "Contract is pausing for operation.");
        LockRule memory ruleInfo = lockRules[ruleId];
        require(ruleInfo.isValid, "Staking is invalid.");
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "No more supply.");

        uint256 LOCK_AMOUNT = ruleInfo.lockAmount;
        uint256 fee = LOCK_AMOUNT * FEE_RATE / 10000;
        uint256 lockAmount = LOCK_AMOUNT - fee;
        bool feeSuccess = tokenATT.transferFrom(msg.sender, FEE_HOLDER, fee);
        require(feeSuccess, "Token transfer failed");
        bool lockSuccess = tokenATT.transferFrom(msg.sender, address(this), lockAmount);
        require(lockSuccess, "Token transfer failed");

        // Save user info
        userCurrentLockedId[msg.sender] += 1;
        userLockInfo[msg.sender][userCurrentLockedId[msg.sender]] = LockInfo(
            ruleId, msg.sender, userCurrentLockedId[msg.sender],
            lockAmount, block.timestamp, UNLOCK_DURATION,
            block.timestamp + UNLOCK_DURATION, ruleInfo.rewardsAmount, false
        );

        // Send rewards
        SUPPLY_LIMIT -= ruleInfo.rewardsAmount;
        require(SUPPLY_LIMIT >= ruleInfo.rewardsAmount, "Insufficient supply limit.");
        (bool rewardSuccess, ) = payable(msg.sender).call{value: ruleInfo.rewardsAmount}("");
        require(rewardSuccess, "Rewards failed");


        emit Lock(msg.sender, ruleId, lockAmount, block.timestamp);
    }

