function mint() external {
    MintStatus status = mintStatus();
    if (status != MintStatus.Active) {
      revert MintNotActive(status);
    }

    if (hasMinted[msg.sender]) {
      revert AlreadyMinted(msg.sender);
    }

    uint256 tokenId = _nextTokenId;

    if (tokenId > MAX_SUPPLY) {
      revert MaxSupplyReached();
    }

    hasMinted[msg.sender] = true;

    unchecked {
      _nextTokenId = tokenId + 1;
    }

    _safeMint(msg.sender, tokenId);
  }

function mintStatus() public view returns (MintStatus) {
    if (mintClosed) {
      return MintStatus.Closed;
    }
    if (block.timestamp < mintStartTime) {
      return MintStatus.NotStarted;
    }
    if (block.timestamp >= mintEndTime) {
      return MintStatus.Ended;
    }
    return MintStatus.Active;
  }

function _safeMint(address to, uint256 tokenId) internal {
        _safeMint(to, tokenId, "");
    }

function _safeMint(address to, uint256 tokenId, bytes memory data) internal virtual {
        _mint(to, tokenId);
        ERC721Utils.checkOnERC721Received(_msgSender(), address(0), to, tokenId, data);
    }

function _mint(address to, uint256 tokenId) internal {
        if (to == address(0)) {
            revert ERC721InvalidReceiver(address(0));
        }
        address previousOwner = _update(to, tokenId, address(0));
        if (previousOwner != address(0)) {
            revert ERC721InvalidSender(address(0));
        }
    }

function checkOnERC721Received(
        address operator,
        address from,
        address to,
        uint256 tokenId,
        bytes memory data
    ) internal {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(operator, from, tokenId, data) returns (bytes4 retval) {
                if (retval != IERC721Receiver.onERC721Received.selector) {
                    // Token rejected
                    revert IERC721Errors.ERC721InvalidReceiver(to);
                }
            } catch (bytes memory reason) {
                if (reason.length == 0) {
                    // non-IERC721Receiver implementer
                    revert IERC721Errors.ERC721InvalidReceiver(to);
                } else {
                    assembly ("memory-safe") {
                        revert(add(reason, 0x20), mload(reason))
                    }
                }
            }
        }
    }

function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }

function _update(
    address to,
    uint256 tokenId,
    address auth
