    if (mintClosed) {
      return MintStatus.Closed;
    }
    if (block.timestamp < mintStartTime) {
      return MintStatus.NotStarted;
    }
    if (block.timestamp >= mintEndTime) {
      return MintStatus.Ended;
    }
    return MintStatus.Active;
  }

