function registerMerchant(address payoutAddress) external returns (address wrapper) {
        if (payoutAddress == address(0)) revert ZeroAddress();
        wrapper = Clones.clone(wrapperImplementation);
        SettlementWrapper(wrapper)
            .initialize(msg.sender, payoutAddress, address(this), address(registry), pool, stablecoin);
        registry.registerMerchant(msg.sender, wrapper);
        emit MerchantRegistered(msg.sender, wrapper, payoutAddress);
    }

function clone(address implementation) internal returns (address instance) {
        return clone(implementation, 0);
    }

function clone(address implementation, uint256 value) internal returns (address instance) {
        if (address(this).balance < value) {
            revert Errors.InsufficientBalance(address(this).balance, value);
        }
        assembly ("memory-safe") {
            // Cleans the upper 96 bits of the `implementation` word, then packs the first 3 bytes
            // of the `implementation` address with the bytecode before the address.
            mstore(0x00, or(shr(232, shl(96, implementation)), 0x3d602d80600a3d3981f3363d3d373d3d3d363d73000000))
            // Packs the remaining 17 bytes of `implementation` with the bytecode after the address.
            mstore(0x20, or(shl(120, implementation), 0x5af43d82803e903d91602b57fd5bf3))
            instance := create(value, 0x09, 0x37)
        }
        if (instance == address(0)) {
            revert Errors.FailedDeployment();
        }
    }

