function _callOptionalReturn(IERC20 token, bytes memory data) private {
        uint256 returnSize;
        uint256 returnValue;
        assembly ("memory-safe") {
            let success := call(gas(), token, 0, add(data, 0x20), mload(data), 0, 0x20)
            // bubble errors
            if iszero(success) {
                let ptr := mload(0x40)
                returndatacopy(ptr, 0, returndatasize())
                revert(ptr, returndatasize())
            }
            returnSize := returndatasize()
            returnValue := mload(0)
        }

        if (returnSize == 0 ? address(token).code.length == 0 : returnValue != 1) {
            revert SafeERC20FailedOperation(address(token));
        }
    }

function repayWithSelectedToken(RepayParams calldata params) public payable whenNotPaused nonReentrant positionRequired(params.user) {
        uint256 borrowAmount = _repayWithSelectedToken(params.shares, params.user);
        _repayWithSelectedTokenTransfer(params, borrowAmount);
        emit RepayByPosition(params.user, borrowAmount, params.shares);
    }

