function requestUnstakeFlexible(uint256 _stakeId) external nonReentrant {
        require(
            _stakeId < flexibleStakes[msg.sender].length,
            "Invalid stake ID"
        );
        FlexibleStake storage stake = flexibleStakes[msg.sender][_stakeId];

        require(
            stake.status == FlexibleStakeStatus.STAKING,
            "Stake not active"
        );
        require(
            block.number >= stake.stakeBlock + minWithdrawalRequestBlocks,
            "Too early to request withdrawal"
        );

        updateRewardPool();

        uint256 sharesToBurn = stake.sharesAmount;
        // uint256 hskToReturn = getHSKForShares(sharesToBurn);
        uint256 hskToReturn = getHSKForSharesByType(sharesToBurn, StakeType.FLEXIBLE);

        uint256 maxStakeReward = getStakeFlixableMaxReward(stake);
        // 原始质押金额
        uint256 originalAmount = stake.hskAmount; 
        // 不能超过最大收益
        if (hskToReturn > maxStakeReward + originalAmount) {
             hskToReturn = maxStakeReward + originalAmount;
        }

        uint256 totalShares = stHSK.totalSupply();
        uint256 originalStakeRatio = (sharesToBurn * BASIS_POINTS) /
            totalShares;
        uint256 originalStake = (totalPooledHSK * originalStakeRatio) /
            BASIS_POINTS;
        if (originalStake > hskToReturn) {
            originalStake = hskToReturn;
        }
        uint256 rewardPart = hskToReturn - originalStake;

        totalPooledHSK -= originalStake;
        if (rewardPart > 0) {
            if (rewardPart > totalPaidRewards) {
                rewardPart = totalPaidRewards;
            }
            totalPaidRewards -= rewardPart;
            totalPooledHSK -= rewardPart;
        }

        totalSharesByStakeType[StakeType.FLEXIBLE] -= sharesToBurn;

        stHSK.burn(msg.sender, sharesToBurn);

        uint256 claimableBlock = block.number + withdrawalWaitingBlocks;
        pendingWithdrawals[msg.sender].push(
            PendingWithdrawal({
                hskAmount: hskToReturn,
                claimableBlock: claimableBlock,
                claimed: false
            })
        );

        stake.status = FlexibleStakeStatus.WITHDRAWN;

        emit RequestUnstakeFlexible(
            msg.sender,
            _stakeId,
            hskToReturn,
            claimableBlock
        );
    }

function updateRewardPool() public {
        if (block.number <= lastRewardBlock) {
            return;
        }

        if (totalPooledHSK == 0) {
            lastRewardBlock = block.number;
            return;
        }

        uint256 multiplier = block.number - lastRewardBlock;
        uint256 hskReward = multiplier * hskPerBlock;

        // Calculate and limit APR using configurable block time
        // SECONDS_PER_YEAR is 365 days (31,536,000 seconds)
        // Explicitly calculate blocks per year based on the configured block time
        uint256 blocksPerYear = SECONDS_PER_YEAR / blockTime;  // 31,536,000 / blockTime
        uint256 annualReward = hskPerBlock * blocksPerYear;
        uint256 currentAPR = (annualReward * BASIS_POINTS) / totalPooledHSK;
        if (currentAPR > MAX_APR) {
            hskReward = (totalPooledHSK * MAX_APR * multiplier) / (BASIS_POINTS * blocksPerYear);
        }

        // 计算额外的锁定期奖励
        uint256 additionalBonusRewards = 0;

        // 获取总shares数量
        uint256 totalShares = stHSK.totalSupply();

        if (totalShares > 0) {
            // 计算每种锁定期类型的额外奖励
            uint256 bonusReward30Days = 0;
            uint256 bonusReward90Days = 0;
            uint256 bonusReward180Days = 0;
            uint256 bonusReward365Days = 0;
            // 只有当该类型有质押时才计算奖励
            if (totalSharesByStakeType[StakeType.FIXED_30_DAYS] > 0) {
                // 计算该类型质押占总质押的比例
                uint256 shareRatio30Days = (totalSharesByStakeType[StakeType.FIXED_30_DAYS] * PRECISION_FACTOR) / totalShares;
                // 计算该类型的基础奖励
                uint256 baseReward30Days = (hskReward * shareRatio30Days) / PRECISION_FACTOR;
                // 计算该类型的额外奖励
                bonusReward30Days = (baseReward30Days * stakingBonus[StakeType.FIXED_30_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_90_DAYS] > 0) {
                uint256 shareRatio90Days = (totalSharesByStakeType[StakeType.FIXED_90_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward90Days = (hskReward * shareRatio90Days) / PRECISION_FACTOR;
                bonusReward90Days = (baseReward90Days * stakingBonus[StakeType.FIXED_90_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_180_DAYS] > 0) {
                uint256 shareRatio180Days = (totalSharesByStakeType[StakeType.FIXED_180_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward180Days = (hskReward * shareRatio180Days) / PRECISION_FACTOR;
                bonusReward180Days = (baseReward180Days * stakingBonus[StakeType.FIXED_180_DAYS]) / BASIS_POINTS;
            }

            if (totalSharesByStakeType[StakeType.FIXED_365_DAYS] > 0) {
                uint256 shareRatio365Days = (totalSharesByStakeType[StakeType.FIXED_365_DAYS] * PRECISION_FACTOR) / totalShares;
                uint256 baseReward365Days = (hskReward * shareRatio365Days) / PRECISION_FACTOR;
                bonusReward365Days = (baseReward365Days * stakingBonus[StakeType.FIXED_365_DAYS]) / BASIS_POINTS;
            }
            // bonusRewardFlexible 不计算 直接为0
            // 计算总的额外奖励
            additionalBonusRewards = bonusReward30Days + bonusReward90Days + bonusReward180Days + bonusReward365Days;
        }

        // 总奖励 = 基础奖励 + 额外的锁定期奖励
        uint256 totalReward = hskReward + additionalBonusRewards;

        // 检查合约是否有足够的奖励资金
        // 使用annualRewardsBudget来计算可用奖励，而不是依赖实际合约余额
        // !!! 这里需要修改  不需要检查，定期打钱进去
        uint256 availableRewards = reservedRewards;

        if (availableRewards >= totalReward) {
            totalPooledHSK += totalReward;
            reservedRewards -= totalReward;

            // 更新已支付的奖励总量
            totalPaidRewards += totalReward;
            // Update exchange rate
            emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
        } else {
            if (availableRewards > 0) {
                totalPooledHSK += availableRewards;

                // 更新已支付的奖励总量
                totalPaidRewards += availableRewards;

                totalReward = availableRewards;
                reservedRewards = 0;

                // Update exchange rate
                emit ExchangeRateUpdated(totalPooledHSK, stHSK.totalSupply(), getHSKForShares(PRECISION_FACTOR));
            }
            emit InsufficientRewards(totalReward, reservedRewards);
        }

        lastRewardBlock = block.number;
    }

function getHSKForShares(uint256 _sharesAmount) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        return (_sharesAmount * totalPooledHSK + unClaimedRewards) / totalShares;
    }

function getHSKForSharesByType(uint256 _sharesAmount, StakeType stakeType) public view returns (uint256) {
        uint256 totalShares = stHSK.totalSupply();
        if (totalShares == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        if (totalSharesByStakeType[stakeType] == 0) {
            return _sharesAmount; // Initial 1:1 exchange rate
        }
        uint256 totalRewards = hskPerBlock * (block.number - startBlock);
        uint256 unClaimedRewards = totalRewards - totalPaidRewards;

        uint256 ratio = calculateCorrectionFactor(stakeType);
        //  reward 不能超 最大 APR
        uint256 reward = _sharesAmount * unClaimedRewards * ratio / (totalSharesByStakeType[stakeType] * BASIS_POINTS);
        uint256 base =  (_sharesAmount * totalPooledHSK) / totalShares;
        uint256 maxReward = _sharesAmount * maxAPRs[stakeType] / BASIS_POINTS;
        if (reward > maxReward) {
            reward = maxReward;
        }
        return reward + base;
    }

function getStakeFlixableMaxReward(FlexibleStake memory userStake) internal view returns (uint256) {
        // Early return for zero values
        if (userStake.sharesAmount == 0 || userStake.hskAmount == 0) {
            return 0;
        }

        uint256 blocksPassed = block.number > userStake.stakeBlock ? block.number - userStake.stakeBlock : 1;
        // uint256 elapsedTime = block.timestamp - lockStartTime; // 正常计算已经过的时间
        uint256 blocksPerYear = SECONDS_PER_YEAR / blockTime;
        // // uint256 completionYearRatio = elapsedTime * BASIS_POINTS / SECONDS_PER_YEAR;
        uint256 completionYearRatio = blocksPassed * BASIS_POINTS / blocksPerYear;

        // 根据已完成比例调整APR
        uint256 adjustedAPR = (maxAPRs[StakeType.FLEXIBLE] * completionYearRatio) / BASIS_POINTS;
        uint256 maxReward = (userStake.hskAmount * adjustedAPR) / BASIS_POINTS;

        return maxReward;
    }

function totalSupply() public view virtual override returns (uint256) {
        return _totalSupply;
    }

function burn(address from, uint256 sharesAmount) external onlyOwner {
        _burn(from, sharesAmount);
    }

function calculateCorrectionFactor(StakeType stakeType) public view returns (uint256) {
        // 计算所有池的总加权质押量
        uint256 totalWeightedShares = 0;
        for (uint256 i = 0; i < 5; i++) {
            StakeType currentType = StakeType(i);
            totalWeightedShares += maxAPRs[currentType] * totalSharesByStakeType[currentType];
        }
        // 避免除以零
        if (totalWeightedShares == 0) {
            return 1;
        }

        // 计算指定池的加权质押量
        uint256 weightedShares = maxAPRs[stakeType] * totalSharesByStakeType[stakeType];

        // 计算占总质押的百分比
        uint256 percentOfTotalShares = totalSharesByStakeType[stakeType] * BASIS_POINTS / totalWeightedShares;

        // 如果百分比为0，避免除以零
        if (percentOfTotalShares == 0) {
            return (weightedShares * BASIS_POINTS) / totalWeightedShares;
        }

        return (weightedShares * BASIS_POINTS) / totalWeightedShares;
    }

function _burn(address account, uint256 amount) internal virtual {
        require(account != address(0), "ERC20: burn from the zero address");

        _beforeTokenTransfer(account, address(0), amount);

        uint256 accountBalance = _balances[account];
        require(accountBalance >= amount, "ERC20: burn amount exceeds balance");
        unchecked {
            _balances[account] = accountBalance - amount;
            // Overflow not possible: amount <= accountBalance <= totalSupply.
            _totalSupply -= amount;
        }

        emit Transfer(account, address(0), amount);

        _afterTokenTransfer(account, address(0), amount);
    }

function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual {}

function _afterTokenTransfer(address from, address to, uint256 amount) internal virtual {}

function requestWithdraw(
        uint256 withdrawalId,
        bool isForcePending,
        ValidatorInfo[] calldata validators,
        WithdrawAction calldata action,
        bytes[] calldata validatorSignatures,
        uint256 nonce
    ) external whenNotPaused onlyRole(OPERATOR_ROLE) nonReentrant {
        RequestWithdrawLocalVars memory vars;

        _nonceUsedCheckAndSet(nonce);
        _ensureTokenValid(action.token);
        _refillWithdrawHotAmount(action.token);
        _checkWithdrawalExists(withdrawalId, false);
        _checkTokenBalance(action.token, action.amount);

        vars.digest = keccak256(
            abi.encode(
                "requestWithdraw",
                withdrawalId,
                block.chainid,
                address(this),
                action.token,
                action.amount,
                action.fee,
                action.receiver,
                isForcePending,
                nonce
            )
        );

        _verifyValidatorSignature(validators, vars.digest, validatorSignatures);

        vars.isPending = isForcePending;
        if (!isForcePending) {
            // when normal withdrawal triggers hard cap exceeded, fallback to pending mode
            vars.isPending = _increaseUsedWithdrawHotAmount(
                supportedTokens[action.token],
                action.amount
            );
        }
        withdrawals[withdrawalId] = Withdrawal(
            false,
            vars.isPending,
            false,
            action.amount,
            action.token,
            action.fee,
            action.receiver,
            block.timestamp
        );
        emit WithdrawalAdded(
            withdrawalId,
            action.token,
            action.amount,
            action.fee,
            action.receiver,
            vars.isPending,
            isForcePending,
            nonce
        );
        if (!vars.isPending) {
            _executeWithdrawal(withdrawalId, false, false, false, nonce);
        }
    }

function _nonceUsedCheckAndSet(uint256 nonce) internal {
        if (nonceUsed[nonce]) {
            revert NonceAlreadyUsed();
        }
        nonceUsed[nonce] = true;
    }

function _ensureTokenValid(address token) internal view {
        if (!_isTokenSupported(token)) {
            revert TokenInvalid();
        }
    }

function _refillWithdrawHotAmount(address token) internal {
        TokenInfo storage tokenInfo = supportedTokens[token];
        uint256 refillPeriod = block.timestamp - tokenInfo.lastRefillTimestamp;
        if (refillPeriod == 0) {
            return;
        }
        uint256 hardCap = getHardCap(token);
        uint256 refillAmount = (hardCap *
            tokenInfo.refillRateMps *
            refillPeriod) / 1000000;
        uint256 appliedRefillAmount = refillAmount;
        if (tokenInfo.usedWithdrawHotAmount < refillAmount) {
            appliedRefillAmount = tokenInfo.usedWithdrawHotAmount;
            tokenInfo.usedWithdrawHotAmount = 0;
        } else {
            tokenInfo.usedWithdrawHotAmount -= refillAmount;
        }
        tokenInfo.lastRefillTimestamp = block.timestamp;
        emit WithdrawHotAmountRefilled(
            tokenInfo.token,
            appliedRefillAmount,
            tokenInfo.usedWithdrawHotAmount
        );
    }

function _checkWithdrawalExists(
        uint256 id,
        bool shouldExist
    ) internal view {
        bool isExisting = withdrawals[id].timestamp > 0;
        if (isExisting != shouldExist) {
            revert WithdrawalExistenceCheckFailed();
        }
    }

function _checkTokenBalance(
        address token,
        uint256 amount
    ) internal view {
        if (token == address(0) && amount > address(this).balance) {
            revert InsufficientVaultBalance();
        } else if (token != address(0) && amount > IERC20(token).balanceOf(address(this))) {
            revert InsufficientVaultBalance();
        }
    }

function _verifyValidatorSignature(
        ValidatorInfo[] calldata validators,
        bytes32 digest,
        bytes[] calldata validatorSignatures
    ) internal view {
        bytes32 validatorHash = keccak256(abi.encode(validators));
        uint256 totalPower = availableValidators[validatorHash];
        if (totalPower == 0) {
            revert InvalidValidators();
        }
        uint256 requiredPower = validatorRequiredPowers[validatorHash];
        uint256 power = 0;
        uint256 validatorIndex = 0;
        bytes32 validatorDigest = MessageHashUtils.toEthSignedMessageHash(
            digest
        );
        for (
            uint256 signatureIndex = 0;
            signatureIndex < validatorSignatures.length &&
                validatorIndex < validators.length;
            signatureIndex++
        ) {
            (address recovered, ECDSA.RecoverError recoverError, ) = ECDSA.tryRecoverCalldata(
                validatorDigest,
                validatorSignatures[signatureIndex]
            );
            if (recoverError != ECDSA.RecoverError.NoError || recovered == address(0)) {
                continue;
            }
            while (validatorIndex < validators.length) {
                address validator = validators[validatorIndex].signer;
                validatorIndex++;
                if (validator == recovered) {
                    power += validators[validatorIndex - 1].power;
                    break;
                }
            }
        }
        if (power < requiredPower) {
            revert NotEnoughValidatorPower();
        }
    }

function _increaseUsedWithdrawHotAmount(
        TokenInfo storage tokenInfo,
        uint256 amount
    ) internal returns (bool pendingTriggered) {
        uint256 hardCap = getHardCap(tokenInfo.token);
        // hard cap exceeded
        if (tokenInfo.usedWithdrawHotAmount + amount > hardCap) {
            pendingTriggered = true;
        } else {
            tokenInfo.usedWithdrawHotAmount += amount;
        }
        emit WithdrawHotAmountUsed(
            tokenInfo.token,
            amount,
            tokenInfo.usedWithdrawHotAmount,
            pendingTriggered
        );
    }

function _executeWithdrawal(
        uint256 withdrawalId,
        bool isPending,
        bool isFlushed,
        bool isPaused,
        uint256 nonce
    ) internal {
        Withdrawal storage withdrawal = withdrawals[withdrawalId];
        withdrawal.executed = true;
        _transfer(
            payable(withdrawal.receiver),
            withdrawal.token,
            withdrawal.amount,
            withdrawal.fee
        );
        emit WithdrawExecuted(
            withdrawalId,
            withdrawal.receiver,
            withdrawal.token,
            withdrawal.amount,
            withdrawal.fee,
            isPending,
            isFlushed,
            isPaused,
            nonce
        );
    }

function _isTokenSupported(address token) internal view returns (bool) {
        return supportedTokens[token].hardCapRatioBps != 0;
    }

function getHardCap(address token) public view returns (uint256) {
        TokenInfo storage tokenInfo = supportedTokens[token];
        uint256 balance = token == address(0)
            ? address(this).balance
            : IERC20(token).balanceOf(address(this));
        return (balance * tokenInfo.hardCapRatioBps) / 10000;
    }

function toEthSignedMessageHash(bytes32 messageHash) internal pure returns (bytes32 digest) {
        assembly ("memory-safe") {
            mstore(0x00, "\x19Ethereum Signed Message:\n32") // 32 is the bytes-length of messageHash
            mstore(0x1c, messageHash) // 0x1c (28) is the length of the prefix
            digest := keccak256(0x00, 0x3c) // 0x3c is the length of the prefix (0x1c) + messageHash (0x20)
        }
    }

function toEthSignedMessageHash(bytes memory message) internal pure returns (bytes32) {
        return
            keccak256(bytes.concat("\x19Ethereum Signed Message:\n", bytes(Strings.toString(message.length)), message));
    }

function requestWithdraw(
        uint256 withdrawalId,
        bool isForcePending,
